<!doctype html><html><head><meta charset="utf-8"><style>body{font-family:Arial,sans-serif;font-size:8px}h1{text-align:center;font-size:14px}table{border-collapse:collapse;width:100%;font-size:7px}th,td{border:1px solid #333;padding:3px;text-align:center}th{background:#d9e2f3}td:nth-child(2){text-align:left}.title{text-align:center}</style></head><body><h1>SCHOOL-BASED FEEDING PROGRAM - RECORD OF DAILY FEEDING</h1><p class="title">For the month of {{ date('F', mktime(0,0,0,$month->month,1)) }}, SY {{ $month->schoolYear->year }}</p><table><thead><tr><th>No.</th><th>Name of Pupil</th><th>Grade Level</th><th>Section</th>@foreach(range(1,20) as $day)<th>{{ $day }}</th>@endforeach</tr></thead><tbody>@foreach($students as $student)<tr><td>{{ $student['number'] }}</td><td>{{ $student['name'] }}</td><td>{{ $student['grade_level'] === 0 ? 'Kinder' : ($student['grade_level'] === 7 ? 'SPED' : 'Grade '.$student['grade_level']) }}</td><td>{{ $student['section'] }}</td>@foreach($student['days'] as $status)<td>{{ in_array(strtolower((string)$status),['present','p','served']) ? 'P' : (in_array(strtolower((string)$status),['absent','a']) ? 'A' : '') }}</td>@endforeach</tr>@endforeach</tbody></table></body></html>
